import os, json, ssl
import urllib.request
import urllib.error

ax_url  = os.environ.get('ADAPTIX_API_URL', '').strip()
ax_user = os.environ.get('ADAPTIX_USERNAME', '').strip()
ax_pass = os.environ.get('ADAPTIX_PASSWORD', '')

# The shipped .env carries REPLACE_WITH_* placeholders. Treat those as "not
# configured" so a stack that never wired up Adaptix does not attempt a doomed
# connection on every 5-minute tick.
def _placeholder(v):
    return v.upper().startswith('REPLACE_WITH')

if not ax_url or _placeholder(ax_url):
    return [{'json': {'fetch_ok': False, 'configured': False,
                      'error': 'ADAPTIX_API_URL is not set (or still the .env placeholder)',
                      'agents': []}}]
if not ax_user or _placeholder(ax_user):
    return [{'json': {'fetch_ok': False, 'configured': False,
                      'error': 'ADAPTIX_USERNAME is not set (or still the .env placeholder)',
                      'agents': []}}]
if _placeholder(ax_pass):
    return [{'json': {'fetch_ok': False, 'configured': False,
                      'error': 'ADAPTIX_PASSWORD is still the .env placeholder',
                      'agents': []}}]

base = ax_url.rstrip('/')

# The teamserver's TLS is operator-generated and typically self-signed, exactly as
# with the Cobalt Strike team server in workflow 01.
ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE


def _post_json(url, payload, headers=None):
    body = json.dumps(payload).encode('utf-8')
    hdrs = {'Content-Type': 'application/json'}
    hdrs.update(headers or {})
    req = urllib.request.Request(url, data=body, headers=hdrs, method='POST')
    with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
        return json.loads(r.read())


def _get_json(url, headers=None):
    req = urllib.request.Request(url, headers=headers or {}, method='GET')
    with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
        return json.loads(r.read())


# ── Step 1: authenticate ──────────────────────────────────────────────────────
# Adaptix issues no static API token; a short-lived access_token is minted per
# login. Each n8n run is a fresh process with nowhere to cache one, so at a
# 5-minute cadence a login per poll is cheaper than /refresh bookkeeping.
try:
    auth = _post_json(base + '/login', {'username': ax_user, 'password': ax_pass})
    token = (auth or {}).get('access_token', '')
    if not token:
        return [{'json': {'fetch_ok': False,
                          'error': 'Adaptix login returned no access_token',
                          'agents': []}}]
except urllib.error.HTTPError as e:
    # A REJECTED LOGIN ANSWERS 404, not 401 -- the teamserver serves its 404 page
    # for unauthenticated requests, so bad credentials and a bad URL are
    # indistinguishable by status code. Say so, or the operator spends the
    # engagement hunting a URL typo that isn't there.
    if e.code == 404:
        return [{'json': {'fetch_ok': False, 'agents': [],
                          'error': ('Adaptix login HTTP 404 - the teamserver answers a '
                                    'REJECTED LOGIN with its 404 page, so this is most '
                                    'likely bad credentials. If they are known good, check '
                                    'ADAPTIX_API_URL includes the endpoint prefix from the '
                                    "teamserver's profile.json (e.g. /endpoint).")}}]
    return [{'json': {'fetch_ok': False, 'error': 'Adaptix login HTTP ' + str(e.code),
                      'agents': []}}]
except Exception as e:
    return [{'json': {'fetch_ok': False, 'error': 'Adaptix login failed: ' + repr(e),
                      'agents': []}}]

# ── Step 2: pull the roster ───────────────────────────────────────────────────
try:
    payload = _get_json(base + '/agent/list', {'Authorization': 'Bearer ' + token})

    if isinstance(payload, list):
        agents = payload
    elif isinstance(payload, dict):
        agents = None
        for key in ('agents', 'data', 'items'):
            if isinstance(payload.get(key), list):
                agents = payload[key]
                break
        if agents is None:
            agents = []
    else:
        agents = []

    return [{'json': {'fetch_ok': True, 'error': '', 'agents': agents}}]
except urllib.error.HTTPError as e:
    body = ''
    try:
        body = e.read().decode('utf-8', errors='replace')[:300]
    except Exception:
        body = ''
    if e.code == 404:
        return [{'json': {'fetch_ok': False, 'agents': [],
                          'error': ('Adaptix /agent/list HTTP 404 - the access token was '
                                    'rejected (the teamserver 404s unauthenticated requests '
                                    'rather than 401ing)')}}]
    return [{'json': {'fetch_ok': False, 'agents': [],
                      'error': 'Adaptix API HTTP ' + str(e.code) + ': ' + body}}]
except Exception as e:
    return [{'json': {'fetch_ok': False, 'error': 'Adaptix API request failed: ' + repr(e),
                      'agents': []}}]
